import { fetchKulturhusetEvents } from './src/sources/kulturhuset';
import { queueEvents } from './src/sources/sourceRunner';
async function test() {
  console.log('Fetching Kulturhuset events...');
  const events = await fetchKulturhusetEvents({ limit: 3 });

  console.log('Events fetched:');
  events.forEach(e => console.log('  URL:', e.url, '- Title:', e.title.substring(0, 40)));

  console.log('\nQueueing events...');
  const result = await queueEvents(events, 'kulturhuset');
  console.log('Queued:', result);
}
test().catch(console.error);
